    'web.challenge.why.c2.p': 'एक कार्यस्थान में कई एजेंटों को प्रबंधित और व्यवस्थित करें, प्रति कार्य रूपरेखा और मॉडल चुनें: हल्के काम के लिए सस्ते स्तर, शीर्ष मॉडल जहां निर्णय मायने रखता है।',
    'web.challenge.why.c3.h': 'अपना काम दिखाओ',
    'web.challenge.why.c3.p': 'फाइनलिस्ट को डेमो दिवस पर प्रस्तुति देने के लिए आमंत्रित किया जाता है। प्रेजेंटेशन पूरा करने वाला प्रत्येक प्रोजेक्ट जीतता है: शीर्ष तीन को स्थान पुरस्कार मिलता है, और अन्य सभी को सम्मानजनक उल्लेख मिलता है।',
    'web.challenge.cases.h2a': 'निश्चित नहीं कि क्या बनाया जाए? ए से शुरू करें',
    'web.challenge.cases.h2x': 'डेमो',
    'web.challenge.cases.h2b': '',
    'web.challenge.cases.p': 'Manyfold पर चलने वाली वास्तविक परियोजनाएँ - एक खोलें और इसे लाइव आज़माएँ। गेटेड डेमो कार्ड पर अपना एक्सेस कोड दिखाते हैं।',
    'web.challenge.cases.codeLabel': 'एक्सेस कोड',
    'web.challenge.cases.codeCopied': 'कॉपी किया गया',
    'web.challenge.case1.p': 'एक हैकर समाचार लिंक, एक लेख URL या कच्चा पाठ चिपकाएं, और एजेंटों का एक पिक्सेल कार्यालय इसे प्राप्त करता है, विच्छेदित करता है और इस पर बहस करता है - पूरे रन की लाइव कल्पना की जाती है।',
    'web.challenge.case1.t1': 'लेख विश्लेषण',
    'web.challenge.case1.t2': 'पिक्सेल विज़ुअलाइज़ेशन',
    'web.challenge.case1.link': 'मामला देखें',
    'web.challenge.case2.p': 'एक वाक्य में किसी यात्रा का वर्णन करें - एजेंट संक्षेप में विश्लेषण करते हैं, समय क्षेत्र की जांच करते हैं, लाइव वेब खोज के साथ गंतव्यों पर शोध करते हैं और टिकट-शैली की दिन-प्रतिदिन की पुस्तिका प्रिंट करते हैं।',
    'web.challenge.case2.t1': 'मल्टी-एजेंट पाइपलाइन',
    'web.challenge.case2.t2': 'लाइव वेब अनुसंधान',
    'web.challenge.case2.link': 'मामला देखें',
    'web.challenge.case3.p': 'एक द्विभाषी चैनल कार्यक्षेत्र जहां लोग और A2A एजेंट वास्तविक समय में सहयोग करते हैं - एक एजेंट का उल्लेख करें और यह सीधे थ्रेड में उत्तर देता है।',
    'web.challenge.case3.t1': 'A2A एजेंट',
    'web.challenge.case3.t2': 'वास्तविक समय सहयोग',
    'web.challenge.case3.link': 'मामला देखें',
    'web.challenge.req.h2a': 'क्या करें?',
    'web.challenge.req.h2x': 'जमा करें',
    'web.challenge.req.h2b': '',
    'web.challenge.req.p': 'यह चुनौती एकल प्रतिभागियों के लिए है; प्रत्येक प्रवेशकर्ता स्वतंत्र रूप से पंजीकरण और सबमिट करता है। एक बार साइन अप करने के बाद, Manyfold के साथ निर्माण शुरू करें; बाकी परिभाषित करना आपका है।',
    'web.challenge.req.rule1.title': 'Manyfold में कोर बनाएं',
    'web.challenge.req.rule1.body': 'अपने एजेंट परिनियोजन, ऑर्केस्ट्रेशन या कॉल के लिए Manyfold का उपयोग करें। प्रारूप आपके ऊपर निर्भर है.',
    'web.challenge.req.rule2.title': 'इसे प्रयोग योग्य बनायें',
    'web.challenge.req.rule2.body': 'किसी सुलभ सेवा या डेमो को उसके द्वारा हल की जाने वाली समस्या पर कुछ शब्दों के साथ साझा करें।',
    'web.challenge.req.rule3.title': 'अपनी पसंद स्पष्ट करें',
    'web.challenge.req.rule3.body': 'दिखाएँ कि कैसे एजेंट, ढाँचे और मॉडल काम को विभाजित करते हैं। लागत, दक्षता और प्रसन्नता सभी मायने रखती हैं।',
    'web.challenge.req.note.title': 'इसे जटिल होने की आवश्यकता नहीं है.',
    'web.challenge.req.note.body': 'एक छोटा उपकरण जो विश्वसनीय रूप से काम करता है और पुनः उपयोग किया जा सकता है वह एक बड़ी अवधारणा की तुलना में अधिक मजबूत प्रविष्टि है जो चल नहीं सकती है।',
    'web.challenge.judge.h2a': 'मूल्यांकन',
    'web.challenge.judge.h2x': 'मानदंड',
    'web.challenge.judge.h2b': '',
    'web.challenge.judge.p': 'प्रत्येक परियोजना मूल्यांकन की तीन परतों से गुजरती है, और फाइनलिस्ट डेमो दिवस पर लाइव उपस्थित होते हैं। प्रेजेंटेशन पूरा करने वाला प्रत्येक प्रोजेक्ट जीतता है, उपस्थित लोग अंतिम रैंकिंग पर मतदान करते हैं।',
    'web.challenge.judge.pts': 'अंक',
