    'web.challenge.tl.s2.when': '7 अगस्त, 15:00',
    'web.challenge.tl.s2.h': 'ऑनलाइन सत्र',
    'web.challenge.tl.s2.p': 'प्रश्नोत्तरी के साथ प्रवाह और सबमिशन का लाइव वॉकथ्रू।',
    'web.challenge.tl.s3.when': '12 अगस्त, 24:00',
