    'web.landing.capSkillsTitle': 'किसी भी GitHub रेपो से क्षमताएं स्थापित करें।',
    'web.landing.capSkillsBody': 'प्रति एजेंट संस्करणित, पिन किया हुआ, स्कोप्ड। रेपो को फिक्स भेजें, प्रत्येक एजेंट इसे उठा लेता है। कोई कांटा नहीं, कोई गोंद कोड नहीं - रनटाइम उन्हें मूल रूप से लोड करता है।',
