    'web.landing.capAutomationsBody': 'वही एजेंट, कोई मानवीय संकेत नहीं। क्रॉन, GitHub ईवेंट, Slack उल्लेख, इनबाउंड ईमेल - सभी एजेंट को एक ही कार्यक्षेत्र में, एक ही ऑडिट ट्रेल के साथ जगाते हैं।',
