    'web.channels.settings.connection.websocket': 'WebSocket (लंबा कनेक्शन)',
    'web.channels.settings.connectionHelp.matrix': 'API बॉट एक्सेस टोकन के साथ Matrix /sync को पोल करता है — किसी सार्वजनिक URL या callback कॉन्फ़िगरेशन की आवश्यकता नहीं। एन्क्रिप्टेड रूम समर्थित नहीं हैं; एन्क्रिप्टेड इवेंट छोड़ दिए जाते हैं।',
    'web.channels.settings.connectionHelp.discord': 'API एक Discord Gateway कनेक्शन बनाए रखता है — किसी सार्वजनिक URL या callback कॉन्फ़िगरेशन की आवश्यकता नहीं। सुनिश्चित करें कि Developer Portal में Bot → Privileged Gateway Intents के अंतर्गत MESSAGE_CONTENT सक्षम है।',
    'web.channels.settings.connectionHelp.weixin': 'API बॉट टोकन के साथ Tencent iLink बॉट गेटवे को लॉन्ग-पोल करता है — किसी सार्वजनिक URL की आवश्यकता नहीं। पर्सनल WeChat केवल डायरेक्ट-मैसेज है; ग्रुप चैट डिलीवर नहीं होते। यदि सत्र समाप्त हो जाता है (errcode -14), तो QR कोड फिर से स्कैन करें और टोकन अपडेट करें।',
    'web.channels.settings.webhookHelp.telegram': 'क्रेडेंशियल सहेजे जाने पर Telegram webhook अपने आप रजिस्टर हो जाता है — कुछ भी पेस्ट करने की ज़रूरत नहीं।',
    'web.channels.settings.webhookHelp.slack': 'इस URL को अपने Slack ऐप में Event Subscriptions → Request URL के अंतर्गत पेस्ट करें।',
    'web.channels.settings.webhookHelp.lark': 'इसे {{platform}} Open Platform → Event Subscriptions → Request URL में पेस्ट करें।',
    'web.channels.settings.webhookHelp.github': '"Create GitHub App" फ़्लो यह webhook URL ऐप पर अपने आप सेट कर देता है; खुद बनाए गए ऐप के लिए, इसे issues और issue_comment इवेंट के साथ ऐप webhook URL के रूप में सेट करें।',
    'web.channels.settings.webhookHelp.other': 'इस URL को अपने प्रदाता के event subscription कॉन्फ़िगरेशन में पेस्ट करें।',
    'web.channels.settings.webhookHelp.line': 'क्रेडेंशियल सहेजने पर LINE का webhook URL अपने आप सेट हो जाता है — कुछ पेस्ट करने की ज़रूरत नहीं। LINE Developers कंसोल में Messaging API के तहत "Use webhook" चालू करें, और वहीं ऑटो-रिप्लाई संदेश बंद करें ताकि बॉट दो बार जवाब न दे।',
    'web.channels.settings.github.title': 'GitHub ऐप',
    'web.channels.settings.github.connectedAs': 'कनेक्टेड के रूप में',
    'web.channels.settings.github.mentionHint': '. टर्न शुरू करने के लिए इसे किसी इशू या कमेंट में मेंशन करें।',
    'web.channels.settings.github.install': 'रिपॉज़िटरी पर इंस्टॉल करें',
    'web.channels.settings.github.installHint': 'ऐप को उन सभी रिपॉज़िटरी पर इंस्टॉल होना चाहिए जिन पर एजेंट को जवाब देना है। रिपो write एक्सेस (clone/push/PR) उसी एजेंट से लिंक किए गए GitHub कनेक्शन से मिलती है, इस ऐप से नहीं।',
    'web.channels.settings.github.createHint': 'इस चैनल के लिए एक अलग GitHub App बनाएँ — GitHub अपने आप क्रेडेंशियल वापस भेज देता है और चैनल खुद सक्रिय हो जाता है। इसे अपने पर्सनल अकाउंट पर बनाने के लिए organization खाली छोड़ें।',
    'web.channels.settings.github.create': 'GitHub App बनाएँ',
