    'web.channels.settings.slack.copyManifest': 'manifest JSON कॉपी करें',
    'web.channels.settings.slack.manifestHint': 'मैनिफेस्ट से Slack app बनाएँ और इस JSON को पेस्ट करें। यह इस चैनल के लिए Request URL, event subscriptions, बॉट scopes और सभी slash commands जोड़ देता है। अगर पहले से इंस्टॉल किसी दूसरे app ने कोई कमांड नाम पहले से ले रखा है (जैसे',
    'web.channels.settings.slack.manifestHintSuffix': '), तो Slack इंस्टॉल के समय चेतावनी देगा — पहले मैनिफेस्ट में उसका नाम बदलें। बॉट को हर चैनल में इनवाइट करें ताकि वह पोस्ट कर सके।',
